<?php
namespace Tests\Feature;
use App\Models\Tenant; use App\Models\User; use App\Models\UserPermissionOverride; use Illuminate\Support\Facades\Gate; use Illuminate\Support\Str; use Tests\TestCase;
class GranularPermissionTest extends TestCase { public function test_hr_defaults_can_be_explicitly_denied_while_admin_is_break_glass():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Perm '.Str::random(4)]);try{tenancy()->initialize($tenant);$hr=User::create(['name'=>'HR','email'=>Str::uuid().'@example.test','password'=>'secret123','role'=>'hr']);$admin=User::create(['name'=>'Admin','email'=>Str::uuid().'@example.test','password'=>'secret123','role'=>'company_admin']);$this->actingAs($hr);$this->assertTrue(Gate::allows('payroll.approve'));UserPermissionOverride::create(['user_id'=>$hr->id,'permission'=>'payroll.approve','allowed'=>false]);$this->assertFalse(Gate::forUser($hr)->allows('payroll.approve'));$this->assertTrue(Gate::forUser($admin)->allows('payroll.approve'));}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
